import { createFixture, MAX_IMAGE_SIZE, sha256, digestObject } from './core.js';
import { readAllImages, readState, commit } from './storage.js';
import { signRecord, verifyCertificate, verifyAudit } from './integrity.js';

const paths={
  overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
  drive:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="M3 14h18M7 17h.01M11 17h.01M7 8h10"/>',
  recovery:'<path d="M3 10a9 9 0 1 1 1.7 8M3 4v6h6M12 8v5l3 2"/>',
  certificate:'<path d="M14 3H5v18h14V8zM14 3v5h5M8 12h8M8 16h4"/><path d="m13 18 2 2 4-4"/>',
  activity:'<path d="M3 12h4l3-8 4 16 3-8h4"/>',
  shield:'<path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6z"/><path d="m8 12 3 3 5-6"/>',
  plus:'<path d="M12 5v14M5 12h14"/>', upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v5h16v-5"/>',
  arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',check:'<path d="m5 12 4 4L19 6"/>',
  search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',
  file:'<path d="M14 3H5v18h14V8zM14 3v5h5M8 12h8M8 16h5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',
  lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4M12 14v3"/>',
  download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>', close:'<path d="m6 6 12 12M18 6 6 18"/>',
  external:'<path d="M14 3h7v7M21 3l-11 11M10 3H3v18h18v-7"/>',chain:'<path d="m10 14 4-4M9 16l-2 2a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0M15 8l2-2a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0"/>',
  eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12"/><circle cx="12" cy="12" r="3"/>',
  trash:'<path d="M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
  terminal:'<path d="m4 6 6 6-6 6M13 18h7"/>',cpu:'<rect x="6" y="6" width="12" height="12" rx="2"/><path d="M9 2v4m6-4v4M9 18v4m6-4v4M2 9h4m-4 6h4M18 9h4m-4 6h4"/>',
  loader:'<circle cx="12" cy="12" r="8"/>',print:'<path d="M6 8V3h12v5M6 17H3V8h18v9h-3M6 14h12v7H6zM17 11h.01"/>',
  folder:'<path d="M3 6V4h6l3 3h9v13H3z"/>',flask:'<path d="M9 3h6M10 3v6l-6 10a1 1 0 0 0 1 2h14a1 1 0 0 0 1-2L14 9V3M7 15h10"/>',
};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.file}</svg>`;
const e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const size=n=>n<1024?`${n} B`:n<1048576?`${(n/1024).toFixed(1)} KiB`:`${(n/1048576).toLocaleString(undefined,{maximumFractionDigits:1})} MiB`;
const date=s=>new Date(s).toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});
const short=h=>h?`${h.slice(0,10)}…${h.slice(-8)}`:'—';
const stages=['discover','plan','erase','attack','certify'];
const stageNames={discover:'Discover',plan:'Plan',erase:'Erase',attack:'Attack',certify:'Certify'};
const viewNames={overview:'Overview',media:'Media inventory',recovery:'File recovery',certificates:'Certificates',activity:'Activity log'};
const state={route:'overview',images:[],selected:null,certificates:[],audit:[],scans:{},busy:null,lastJob:null,chainValid:true,menu:false,filter:'all',search:''};
let worker=null,toastTimer=null,renderPending=false,modalReturnFocus=null;
const app=document.querySelector('#app');
const selected=()=>state.images.find(i=>i.id===state.selected)||state.images[0];
const btn=(label,action,ic='',primary=false,extra='')=>{const match=extra.match(/class="([^"]*)"/);const classes=match?match[1]:`button${primary?' primary':''}`;return `<button class="${classes}" data-action="${action}" ${extra.replace(/class="[^"]*"/,'')}>${ic?icon(ic):''}${label}</button>`;};
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),4200);}
function nav(route){if(state.route===route){state.menu=false;render();return;}location.hash=route;}
function requestRender(){if(renderPending)return;renderPending=true;requestAnimationFrame(()=>{renderPending=false;render();});}
function imageOptions(current){return state.images.map(i=>`<option value="${e(i.id)}" ${current===i.id?'selected':''}>${e(i.name)} · ${size(i.size)}</option>`).join('');}
function stats(){const recovered=Object.values(state.scans).reduce((a,s)=>a+s.files.length,0);return `<div class="stats-grid">
  <div class="stat"><div class="stat-top">Available images${icon('drive')}</div><div class="stat-value">${state.images.length}<small>${size(state.images.reduce((n,i)=>n+i.size,0))} total</small></div><div class="stat-foot">${state.images.filter(i=>i.source==='fixture').length} fixtures · ${state.images.filter(i=>i.source!=='fixture').length} imported</div></div>
  <div class="stat"><div class="stat-top">Verified erasures${icon('shield')}</div><div class="stat-value">${state.certificates.length}<small>completed</small></div><div class="stat-foot"><span class="dot"></span>Full image read-back required</div></div>
  <div class="stat"><div class="stat-top">Recovered candidates${icon('recovery')}</div><div class="stat-value">${recovered}<small>files found</small></div><div class="stat-foot">From completed recovery scans</div></div>
  <div class="stat"><div class="stat-top">Audit chain${icon('chain')}</div><div class="stat-value" style="font-size:23px;letter-spacing:-.5px;color:${state.chainValid?'#557a43':'#a2513e'}">${state.chainValid?'Intact':'Mismatch'}</div><div class="stat-foot">${state.audit.length} ${state.audit.length===1?'linked event':'linked events'} · SHA-256</div></div>
  </div>`;}
function pipeline(){return `<section class="panel pipeline-panel"><div class="eyebrow">${icon('shield')} THE ERASEPROOF LOOP</div><h2>Erased is a claim.<br>Verified is evidence.</h2><p>Every wipe is challenged by the same engine built to recover what remains.</p><div class="pipeline">
  ${[['discover','Identify the image boundary'],['plan','Choose a verifiable method'],['erase','Overwrite every image byte'],['attack','Try to recover the residue'],['certify','Sign the measured result']].map(([s,caption],i)=>`<div class="pipeline-step"><span class="step-node">${i===4?icon('check'):String(i+1).padStart(2,'0')}</span><div><strong>${stageNames[s]}</strong><small>${caption}</small></div></div>`).join('')}
  </div><div class="pipeline-caption">${icon('lock')} No certificate if verification fails.</div></section>`;}
function scopePanel(){return `<section class="panel scope-panel"><h3>${icon('flask')} A controlled place to begin</h3><p>Work with seeded fixtures or your own raw images. Processing stays in this browser. Physical drives require a Linux agent.</p><button class="text-button" data-action="help">Understand the scope ${icon('arrow')}</button></section>`;}
function mediaTable(full=false){const images=state.images.filter(i=>(state.filter==='all'||i.status===state.filter)&&(!state.search||`${i.name} ${i.filename}`.toLowerCase().includes(state.search.toLowerCase())));return `<div class="table-wrap"><table><thead><tr><th>Image / source</th><th>Capacity</th><th>State</th><th><span class="hide-mobile">${full?'Actions':'Inspect'}</span></th></tr></thead><tbody>${images.map(i=>`<tr class="clickable ${selected()?.id===i.id?'selected':''}" data-image="${e(i.id)}"><td><div class="media-name"><span class="media-icon">${icon(i.source==='fixture'?'drive':'folder')}</span><div><strong>${e(i.name)}</strong><small>${e(i.filename)} · ${i.source==='fixture'?'FIXTURE':'IMPORTED'}</small></div></div></td><td class="mono">${size(i.size)}</td><td><span class="badge ${i.status==='verified'?'success':'neutral'}">${i.status==='verified'?icon('check'):'<span class="dot"></span>'}${i.status==='verified'?'Verified':'Ready'}</span></td><td><button class="icon-button" data-action="inspect" data-id="${e(i.id)}" aria-label="Inspect ${e(i.name)}">${icon('arrow')}</button></td></tr>`).join('')}</tbody></table>${images.length?'':'<div class="no-match">No images match your filters.</div>'}</div>`;}
function mediaPanel(full=false){return `<section class="panel"><div class="panel-header"><div><h2 class="panel-title">Media inventory <span class="count">${state.images.length}</span></h2><p class="panel-sub">${full?'Raw disk images stored in this browser.':'Your images. Ready for a closer look.'}</p></div>${full?btn('Restore fixtures','fixtures','plus',false, state.busy?'disabled':''):'<button class="text-button" data-action="nav" data-route="media">View all '+icon('arrow')+'</button>'}</div>
  ${full?`<div class="section-toolbar"><div class="search-box">${icon('search')}<input id="media-search" aria-label="Search images" placeholder="Search images…" value="${e(state.search)}"></div><select id="media-filter" aria-label="Filter images"><option value="all" ${state.filter==='all'?'selected':''}>All states</option><option value="ready" ${state.filter==='ready'?'selected':''}>Ready</option><option value="verified" ${state.filter==='verified'?'selected':''}>Verified</option></select></div>`:''}
  <div id="media-table">${mediaTable(full)}</div>
  ${full?`<div class="upload-drop" id="upload-drop" role="button" tabindex="0" aria-label="Import a raw disk image" data-action="import">${icon('upload')}<div><strong>Drop a raw image here</strong><p>or choose a file · .img, .raw, .bin, .dd · up to 128 MiB</p></div></div>`:`<div class="panel-footer"><span class="selected-caption">${icon('info')} Select an image to prepare an erasure.</span><span class="mono">${state.images.length} ${state.images.length===1?'image':'images'}</span></div>`}</section>`;}
function recent(){const jobs=state.audit.filter(a=>a.event==='erasure.completed').slice(-3).reverse();return `<section class="panel"><div class="panel-header"><div><h2 class="panel-title">Recent erasures</h2><p class="panel-sub">A record of what happened. Proof of what remains.</p></div><button class="text-button" data-action="nav" data-route="activity">Activity log ${icon('arrow')}</button></div>${jobs.length?`<div class="table-wrap"><table><thead><tr><th>Image</th><th>Verification</th><th>Completed</th><th>Record</th></tr></thead><tbody>${jobs.map(j=>`<tr><td><div class="media-name"><span class="media-icon">${icon('shield')}</span><div><strong>${e(j.detail.name)}</strong><small>FULL IMAGE OVERWRITE</small></div></div></td><td><span class="badge success">${icon('check')} Passed</span></td><td style="font-size:9px">${date(j.at)}</td><td><button class="icon-button" data-action="certificate" data-id="${e(j.detail.certificateId)}" aria-label="View verification record">${icon('certificate')}</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><span class="empty-icon">${icon('activity')}</span><h3>Your first proof starts here.</h3><p>Run an erasure on a fixture. We’ll overwrite the image, challenge the result, and record the evidence.</p><button class="text-button" data-action="erase" ${state.busy||!state.images.length?'disabled':''}>Start your first erasure ${icon('arrow')}</button></div>`}</section>`;}
function jobPanel(){const j=state.busy||state.lastJob;if(!j)return'';const done=!state.busy;const passed=done&&!j.failed&&!j.cancelled&&(!j.result||j.result.passed);const current=stages.indexOf(j.stage);return `<section class="job-panel ${done?(passed?'success':'stopped'):''}" aria-live="polite"><div class="job-top"><div class="job-label"><span class="job-icon">${icon(done?(passed?'shield':'info'):'loader',done?'':'spinner')}</span><div><h2>${done?(j.cancelled?'Operation cancelled':j.failed?'Operation stopped':j.kind==='scan'?'Recovery scan complete':j.kind==='verify'?'Verification complete':'Erasure verified. Evidence signed.'):(j.kind==='scan'?'Searching for recoverable files…':j.kind==='verify'?'Challenging the image…':'Recovery-verified erasure in progress…')}</h2><p>${e(j.name)} · ${size(j.size)} · ${done?`${(j.elapsed/1000).toFixed(2)}s elapsed`:'Processing locally'}</p></div></div>${done?'<button class="icon-button" data-action="dismiss-job" aria-label="Dismiss result">'+icon('close')+'</button>':btn('Cancel','cancel-job','close',false,'class="button small"')}</div>
  ${j.kind==='erase'?`<div class="job-steps">${stages.map((s,i)=>`<div class="job-step ${i<current||passed?'done':''}"><div class="bar"><i style="width:${i<current?100:i===current?j.progress*100:0}%"></i></div><strong>${String(i+1).padStart(2,'0')} ${stageNames[s]}${i<current||passed?icon('check'):''}</strong></div>`).join('')}</div>`:''}
  <div class="job-terminal"><span class="terminal-prompt">›</span><span>${e(j.message)}</span></div>
  ${done&&j.result?`<div class="result-strip"><div>${j.result.rrs===null?'N/A':(j.result.rrs*100).toFixed(0)+'%'}<small>Residual recoverability${j.result.rrs===null?' · no reference set':''}</small></div><div>${j.result.carvedFiles.length}<small>Carved candidates</small></div><div>${size(j.result.bytesChecked)}<small>Image bytes checked</small></div>${j.certificateId?btn('View evidence','certificate','certificate',true,`data-id="${e(j.certificateId)}"`):''}</div>`:''}</section>`;}
function header(){const text={overview:['WORKSPACE OVERVIEW','Erasure workspace','Discover your media. Challenge the wipe. Keep the proof.'],media:['YOUR MEDIA','Media inventory','A clear boundary for every operation. Your original imports stay untouched.'],recovery:['FORENSIC WORKBENCH','See what survives.','Search raw image bytes for recoverable file structures.'],certificates:['VERIFIABLE EVIDENCE','Proof, kept on record.','Signed local records bound to the exact image and verification results.'],activity:['WORKSPACE HISTORY','An unbroken record.','Every workspace event, linked to the one before it.']}[state.route];return `<header class="page-header"><div><div class="eyebrow"><span class="dot"></span>${text[0]}</div><h1>${text[1]}</h1><p>${text[2]}</p></div><div class="header-actions">${state.route==='certificates'?btn('Verify a record','verify-certificate','shield'):state.route==='activity'?btn('Export audit log','export-audit','download'):btn('Import image','import','upload',false,state.busy?'disabled':'')}${['overview','media'].includes(state.route)?btn('New erasure','erase','plus',true,state.busy||!state.images.length?'disabled':''):''}</div></header>`;}
function recovery(){const image=selected(),scan=state.scans[image?.id];return `<div class="detail-layout"><section class="panel"><div class="panel-header"><div><h2 class="panel-title">Recovered candidates ${scan?'<span class="count">'+scan.files.length+'</span>':''}</h2><p class="panel-sub">${scan?'Last scan '+date(scan.at):'Contiguous carving · no file-system metadata required'}</p></div>${scan&&scan.files.length?btn('Export manifest','export-scan','download',false,'class="button small"'):''}</div>${scan?`<div class="results-header"><span>${e(image.name)}</span><span>${size(image.size)} SCANNED</span></div>${scan.files.length?`<div class="table-wrap"><table><thead><tr><th>Candidate / type</th><th>Offset</th><th>Size</th><th>Confidence</th><th>Export</th></tr></thead><tbody>${scan.files.map((f,i)=>`<tr><td><div class="file-cell">${icon('file')}<span>candidate_${String(i+1).padStart(3,'0')}.${f.type.toLowerCase()}</span></div></td><td class="mono">0x${f.offset.toString(16).toUpperCase()}</td><td class="mono">${size(f.length)}</td><td><button class="text-button" data-action="file-detail" data-index="${i}">${f.confidence}%</button><div class="confidence"><i style="width:${f.confidence}%"></i></div></td><td><button class="icon-button" data-action="download-file" data-index="${i}" aria-label="Download candidate ${i+1}">${icon('download')}</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty large"><span class="empty-icon">${icon('shield')}</span><h3>No supported file candidates found.</h3><p>The contiguous signature scan found no PNG, PDF, JPEG or ZIP candidates. Other formats and fragmented files may still exist.</p></div>`}`:`<div class="empty large"><span class="empty-icon">${icon('search')}</span><h3>The bytes tell the story.</h3><p>Choose an image and run a scan. The engine looks for headers, end markers and structural evidence.</p><span class="badge neutral">Read-only · image stays intact</span></div>`}</section><aside class="panel recovery-controls"><div class="form-group"><label class="field-label" for="recovery-image">Target image</label><select id="recovery-image" class="select" ${state.busy?'disabled':''}>${imageOptions(image?.id)}</select></div><div><span class="field-label">Signature library</span><div class="file-types"><span class="file-type">PNG</span><span class="file-type">PDF</span><span class="file-type">JPEG</span><span class="file-type">ZIP</span></div></div>${btn(state.busy?'Operation in progress':'Run recovery scan','scan','search',true,`class="button primary wide" ${state.busy||!image?'disabled':''}`)}<p class="control-note">Scans every byte. Extracted files are downloaded only when you ask.</p><div class="notice">${icon('info')}<span>Confidence measures structural evidence. PNG checks include chunk CRCs; the other formats use boundary checks. Fragmented, encrypted and compressed content may be missed.</span></div></aside></div>`;}
function certificates(){return `<section class="panel"><div class="panel-header"><div><h2 class="panel-title">Verification records <span class="count">${state.certificates.length}</span></h2><p class="panel-sub">ECDSA P-256 signatures · browser-local signing identity</p></div><span class="badge neutral">Self-signed research records</span></div>${state.certificates.length?`<div class="table-wrap"><table><thead><tr><th>Record / image</th><th>Coverage</th><th>Result</th><th>Issued</th><th>Evidence</th></tr></thead><tbody>${[...state.certificates].reverse().map(c=>`<tr><td><div class="media-name"><span class="media-icon">${icon('certificate')}</span><div><strong>${e(c.payload.image.name)}</strong><small>${e(c.payload.id.slice(0,18).toUpperCase())}</small></div></div></td><td class="mono">${size(c.payload.image.size)}</td><td><span class="badge success">${icon('shield')} Read-back passed</span></td><td style="font-size:10px">${date(c.payload.issuedAt)}</td><td><button class="icon-button" data-action="certificate" data-id="${e(c.payload.id)}" aria-label="Open record for ${e(c.payload.image.name)}">${icon('arrow')}</button><button class="icon-button" data-action="export-certificate" data-id="${e(c.payload.id)}" aria-label="Download signed JSON for ${e(c.payload.image.name)}">${icon('download')}</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty large"><span class="empty-icon">${icon('certificate')}</span><h3>Evidence is earned.</h3><p>A record is issued only after complete zero read-back and a recovery attack pass. Start with a fixture to see the full loop.</p>${btn('Prepare an erasure','erase','plus',true,state.busy||!state.images.length?'disabled':'')}</div>`}</section><div class="notice" style="margin-top:18px">${icon('info')}<span>These records verify a workspace image, using a key created in this browser. They do not certify physical-device sanitization, compliance, or the identity of an external operator.</span></div>`;}
function activity(){return `<section class="panel"><div class="panel-header"><div><h2 class="panel-title">Hash-chained audit log <span class="count">${state.audit.length}</span></h2><p class="panel-sub">Each event commits to its content and the previous event’s hash.</p></div><button class="button small" data-action="check-chain">${icon('chain')}Check integrity</button></div>${state.audit.length?`<div class="audit-list">${[...state.audit].reverse().map(a=>`<article class="audit-item"><span class="audit-icon">${icon(a.event==='erasure.completed'?'shield':a.event==='recovery.completed'?'search':a.event.includes('import')?'upload':a.event.includes('removed')?'trash':'activity')}</span><div><h3>${e(eventLabel(a.event))}</h3><p>${e(a.detail.name||a.detail.message||'Workspace event')}${a.detail.size?' · '+size(a.detail.size):''}</p><div class="hash-string">${e(a.hash)}</div></div><time datetime="${e(a.at)}">${date(a.at)}</time></article>`).join('')}</div>`:`<div class="empty large"><h3>A clean starting point.</h3><p>Import an image or run an operation to begin the audit trail.</p></div>`}</section><div class="notice" style="margin-top:18px">${icon('info')}<span>The local chain detects changed entries relative to its saved head. Keep an exported copy externally to detect deletion or replacement of the whole workspace history.</span></div>`;}
function eventLabel(event){return({'workspace.initialized':'Research workspace initialized','fixtures.restored':'Research fixtures restored','image.imported':'Disk image imported','image.removed':'Image removed from workspace','recovery.completed':'Recovery scan completed','erasure.completed':'Erasure verified and record signed','verification.completed':'Image verification completed','operation.cancelled':'Operation cancelled','operation.failed':'Operation failed'})[event]||event;}
function render(){
  try{if(selected())localStorage.setItem('eraseproof-selected-image',selected().id);}catch{}
  app.innerHTML=`<div class="shell ${state.menu?'menu-open':''}"><aside class="sidebar" aria-label="Workspace navigation"><a class="brand" href="#overview" aria-label="EraseProof overview"><span class="logo-mark">${icon('terminal')}</span>EraseProof<small>LAB</small></a><div class="workspace-switch"><span class="workspace-icon">${icon('flask')}</span><div><strong>Research workspace</strong><small>Disk image environment</small></div><span class="dot"></span></div><div class="nav-caption">WORKSPACE</div><nav class="navigation">${Object.entries(viewNames).map(([r,n])=>`<a class="nav-link ${state.route===r?'active':''}" href="#${r}" ${state.route===r?'aria-current="page"':''}>${icon(r==='media'?'drive':r==='certificates'?'certificate':r)}<span>${n}</span>${r==='certificates'&&state.certificates.length?`<span class="nav-count">${state.certificates.length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="sandbox-note"><div class="small-label">${icon('lock')} LOCAL BY DESIGN</div><p>Your image data stays in this browser. No uploads. No cloud processing.</p></div><button class="help-link" data-action="help">${icon('info')} About this workbench ${icon('external')}</button></div></aside><div class="main-shell"><div class="topbar"><div class="breadcrumbs"><button class="mobile-menu" data-action="menu" aria-label="Toggle navigation" aria-expanded="${state.menu}">${icon('menu')}</button><span>Workspace</span><span class="slash">/</span><strong>${viewNames[state.route]}</strong></div><div class="topbar-right"><span class="local-status"><span class="dot"></span>Browser storage</span><span class="avatar" title="Local research workspace">EP</span></div></div><main class="content" id="main" tabindex="-1">${header()}${state.route==='overview'?stats():''}${jobPanel()}${state.route==='overview'?`<div class="grid-main"><div class="left-stack">${mediaPanel()}${recent()}</div><div class="right-stack">${pipeline()}${scopePanel()}</div></div>`:state.route==='media'?mediaPanel(true):state.route==='recovery'?recovery():state.route==='certificates'?certificates():activity()}<footer class="footer"><span>${icon('shield')} ERASEPROOF / RECOVERY-VERIFIED ERASURE</span><span>IMAGE LAB v0.1 <span>·</span> <a href="#" data-action="help">Scope & methodology</a></span></footer></main></div></div>`;
  document.title=`EraseProof — ${viewNames[state.route]}`;
  bindDrop();
}
function modal(title,body,footer='',wide=false,eyebrow='ERASEPROOF / IMAGE LAB'){
  const root=document.querySelector('#modal-root');if(!root.firstChild)modalReturnFocus=document.activeElement;
  root.innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><div><div class="eyebrow">${eyebrow}</div><h2 id="modal-title">${title}</h2></div><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;
  document.body.style.overflow='hidden';document.querySelector('#app').inert=true;
  root.querySelector('select,input,button')?.focus();
}
function closeModal(){document.querySelector('#modal-root').innerHTML='';document.querySelector('#app').inert=false;document.body.style.overflow='';if(modalReturnFocus?.isConnected)modalReturnFocus.focus();else document.querySelector('[data-action="erase"]')?.focus();}
function prepareErase(){if(state.busy)return toast('Wait for the current operation to finish.');if(!selected())return toast('Import an image or restore the research fixtures first.');modal('Prepare an erasure',`<div class="form-group"><label class="field-label" for="erase-image">Target workspace image</label><select class="select" id="erase-image">${imageOptions(selected()?.id)}</select><p class="form-hint">The original file on your computer will not be changed.</p></div><div class="form-group"><span class="field-label">Erasure plan</span><div class="method-option"><span class="method-radio"></span><div><strong>Full-image zero overwrite</strong><small>One pass over the complete image. Then full zero read-back, contiguous carving, and known-residue search.</small></div></div></div><div class="notice">${icon('shield')}<span>Evidence is issued only if every image byte reads zero and the recovery checks pass. RRS is available only for fixtures with known reference data.</span></div><label class="checkbox-label"><input type="checkbox" id="erase-consent"><span>I understand this replaces the selected workspace image’s bytes. I can keep a copy using “Download image” before continuing.</span></label><div class="inline-error" id="erase-error" role="alert"></div>`,btn('Cancel','close-modal')+btn('Erase & verify','confirm-erase','shield',true,'disabled'));}
async function inspect(id){const image=state.images.find(i=>i.id===id);if(!image)return;state.selected=id;render();const hash=await sha256(image.buffer);modal('Image details',`<div class="detail-heading"><span class="media-icon">${icon('drive')}</span><div><h3>${e(image.name)}</h3><p>${e(image.filename)}</p></div></div><dl class="detail-grid"><div><dt>Capacity</dt><dd>${size(image.size)} · ${image.size.toLocaleString()} bytes</dd></div><div><dt>Origin</dt><dd>${image.source==='fixture'?'Seeded research fixture':'Imported raw image'}</dd></div><div><dt>State</dt><dd>${image.status==='verified'?'Verified zero image':'Ready for analysis'}</dd></div><div><dt>Reference set</dt><dd>${image.manifest.length?image.manifest.length+' known records':'None · RRS unavailable'}</dd></div><div><dt>Added</dt><dd>${date(image.created)}</dd></div><div><dt>Format</dt><dd>Raw bytes · no filesystem mounting</dd></div><div class="full"><dt>Current image SHA-256</dt><dd class="mono">${hash}</dd></div></dl>${image.manifest.length?'<h3 class="section-label">Seeded ground truth</h3><ul class="check-list">'+image.manifest.map(f=>`<li>${icon('file')}${e(f.name)} <span class="mono">0x${f.start.toString(16)}</span></li>`).join('')+'</ul>':''}<div class="notice" style="margin-top:20px">${icon('info')}<span>Physical device properties, file systems, NVMe/ATA capabilities, hidden areas and flash remanence are not detected in image mode.</span></div>`,btn('Remove image','remove-image','trash',false,`data-id="${e(id)}" ${state.busy?'disabled':''}`)+btn('Download image','download-image','download',false,`data-id="${e(id)}"`)+btn('Verify image','verify-image','search',true,state.busy?'disabled':''),true);}
async function auditEntry(event,detail){const item={version:1,sequence:state.audit.length+1,event,at:new Date().toISOString(),detail,previousHash:state.audit.at(-1)?.hash||'0'.repeat(64)};return {...item,hash:await digestObject(item)};}
async function appendAudit(event,detail,extras={}){const entry=await auditEntry(event,detail);const audit=[...state.audit,entry];await commit({values:{audit,...extras}});state.audit=audit;return entry;}
async function checkChain(entries=state.audit){return verifyAudit(entries);}
async function signingKey(){let keys=await readState('signingKey');if(!keys){keys=await crypto.subtle.generateKey({name:'ECDSA',namedCurve:'P-256'},false,['sign','verify']);await commit({values:{signingKey:keys}});}return keys;}
async function makeCertificate(image,result,beforeHash,startedAt){
  const keys=await signingKey();
  const payload={schema:'eraseproof.image-record.v1',id:'ep-'+crypto.randomUUID(),issuedAt:new Date().toISOString(),startedAt,image:{id:image.id,name:image.name,filename:image.filename,size:image.size,source:image.source},method:'Full image zero overwrite; one pass',verification:result,beforeSha256:beforeHash,previousAuditHash:state.audit.at(-1)?.hash||'0'.repeat(64),assurance:'Self-signed local research record. Applies only to the current workspace image bytes. No assertion of device sanitization, operator identity, compliance, or physical remanence.',algorithm:'ECDSA-P256-SHA256'};
  return signRecord(payload,keys);
}
async function run(kind){
  if(state.busy)return;const image=selected();if(!image)return;
  if(kind==='erase'&&!state.chainValid)return toast('Audit integrity failed. Export and inspect the history before creating another erasure record.');
  if(kind==='erase')closeModal();
  const startedAt=new Date().toISOString();state.lastJob=null;
  state.busy={kind,imageId:image.id,name:image.name,size:image.size,stage:kind==='erase'?'discover':'attack',progress:0,message:'Opening a bounded workspace image.',startedAt,start:performance.now()};render();
  worker=new Worker(new URL('./worker.js',import.meta.url),{type:'module'});
  worker.onmessage=async({data})=>{
    if(!state.busy)return;
    if(data.type==='progress'){Object.assign(state.busy,{stage:data.stage,progress:data.value,message:data.message});requestRender();return;}
    if(data.type==='error'){failJob(data.message);return;}
    const currentJob=state.busy;
    try{
      if(data.type==='scan-complete'){
        const scans={...state.scans,[image.id]:{files:data.files,imageHash:data.sha256,at:new Date().toISOString()}};
        await appendAudit('recovery.completed',{name:image.name,size:image.size,candidates:data.files.length,imageHash:data.sha256},{scans});state.scans=scans;
        finishJob({...currentJob,elapsed:performance.now()-currentJob.start,message:`Scan complete. ${data.files.length} contiguous file candidate${data.files.length===1?'':'s'} found.`});toast(`${data.files.length} recoverable candidates found.`);
      }else if(data.type==='verify-complete'){
        await appendAudit('verification.completed',{name:image.name,size:image.size,passed:data.result.passed,imageHash:data.result.sha256});
        finishJob({...currentJob,result:data.result,elapsed:performance.now()-currentJob.start,message:data.result.passed?'All image bytes read zero. Recovery checks passed.':'Residual data remains. No new certificate issued.'});
      }else if(data.type==='erase-complete'){
        if(!data.result.passed)throw new Error('Verification found residue. Workspace image was not replaced and no certificate was issued.');
        Object.assign(state.busy,{stage:'certify',progress:.5,message:'Signing the result and committing image, record and audit event atomically.'});render();
        const certificate=await makeCertificate(image,data.result,data.beforeHash,startedAt);
        const updated={...image,buffer:data.buffer,status:'verified',verifiedAt:certificate.payload.issuedAt};
        const entry=await auditEntry('erasure.completed',{name:image.name,size:image.size,certificateId:certificate.payload.id,imageHash:data.result.sha256,rrs:data.result.rrs});
        const certificates=[...state.certificates,certificate],audit=[...state.audit,entry],scans={...state.scans};delete scans[image.id];
        await commit({images:[updated],values:{certificates,audit,scans}});
        state.images=state.images.map(i=>i.id===image.id?updated:i);state.certificates=certificates;state.audit=audit;state.scans=scans;
        finishJob({...currentJob,stage:'certify',progress:1,result:data.result,certificateId:certificate.payload.id,elapsed:performance.now()-currentJob.start,message:'Full zero read-back passed. No supported file candidates or known reference residues found.'});
        toast('Image verified. Signed evidence is ready.');
      }
    }catch(error){failJob(error.message);}
  };
  worker.onerror=error=>failJob(error.message||'The image worker could not complete this operation.');
  const buffer=image.buffer.slice(0);worker.postMessage({kind,buffer,manifest:image.manifest},[buffer]);
}
function finishJob(job){worker?.terminate();worker=null;state.busy=null;state.lastJob=job;render();}
function failJob(message){if(!state.busy)return;const job=state.busy;finishJob({...job,failed:true,elapsed:performance.now()-job.start,message});toast(message);appendAudit('operation.failed',{name:job.name,message}).then(()=>render()).catch(()=>{});}
async function cancelJob(){if(!state.busy)return;if(state.busy.stage==='certify')return toast('The atomic evidence commit is completing.');const job=state.busy;finishJob({...job,cancelled:true,elapsed:performance.now()-job.start,message:'Worker stopped. The stored image has not been replaced.'});await appendAudit('operation.cancelled',{name:job.name});render();}
function download(data,name,type='application/json'){const blob=data instanceof Blob?data:new Blob([typeof data==='string'||data instanceof ArrayBuffer?data:JSON.stringify(data,null,2)],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
async function certificateModal(id){const c=state.certificates.find(c=>c.payload.id===id);if(!c)return toast('This record is no longer in the workspace.');const valid=await verifyCertificate(c),p=c.payload,r=p.verification;modal('Verification evidence',`<div class="verification-result ${valid?'':'invalid'}"><h3>${icon(valid?'shield':'info')} ${valid?'Signature and payload verified':'Integrity check failed'}</h3><p>${valid?'The embedded public key verifies this record’s signature. The payload hash matches.':'This record has been changed or is invalid.'}</p></div><dl class="detail-grid"><div><dt>Image</dt><dd>${e(p.image.name)} · ${size(p.image.size)}</dd></div><div><dt>Issued</dt><dd>${date(p.issuedAt)}</dd></div><div><dt>Full zero read-back</dt><dd>${r.readbackPassed?'Passed':'Failed'} · ${size(r.bytesChecked)} checked</dd></div><div><dt>Residual Recoverability Score</dt><dd>${r.rrs===null?'N/A · no known reference set':(r.rrs*100).toFixed(0)+'% · known fixture references'}</dd></div><div><dt>Carved candidates</dt><dd>${r.carvedFiles.length}</dd></div><div><dt>Known metadata matches</dt><dd>${r.metadataMatches.length}</dd></div><div class="full"><dt>Image SHA-256 after overwrite</dt><dd class="mono">${e(r.sha256)}</dd></div><div class="full"><dt>Payload SHA-256</dt><dd class="mono">${e(c.payloadSha256)}</dd></div><div class="full"><dt>Record ID</dt><dd class="mono">${e(p.id)}</dd></div></dl><div class="notice">${icon('info')}<span>${e(p.assurance)}</span></div>`,btn('Print record','print','print')+btn('Download signed JSON','export-certificate','download',true,`data-id="${e(id)}"`),true,'ERASEPROOF / SIGNED LOCAL RECORD');}
function help(){modal('Evidence over assumptions.',`<div class="prose"><p>EraseProof pairs erasure with an adversarial recovery check. This first workbench implements that loop on <strong>bounded raw disk images</strong>.</p><h3>What works here</h3><p>Import up to 128 MiB per image, scan for contiguous PNG, PDF, JPEG and ZIP candidates, extract candidates, overwrite the complete workspace image with zeros, verify every byte, search known fixture fingerprints and filenames, and export signed evidence and a hash-chained audit log.</p><h3>What the score means</h3><p>For seeded fixtures, RRS = (matched unique reference blocks + matched known filenames) / (unique reference blocks + known filenames). Blocks are scanned at aligned 4 KiB boundaries. Imported images have no reference set, so RRS is <strong>not available</strong>. All images still require complete zero read-back and no carving candidates to pass.</p><h3>Image verification has a boundary</h3><p>Replacing image bytes in browser storage does not sanitize the original file, physical drive, browser cache, snapshots, or flash remnants. There is no filesystem parsing, PhotoRec, Sleuth Kit, device discovery, ATA/NVMe command or physical-media guarantee here. Those need a privileged Linux engine.</p><h3>Signed, with an explicit identity</h3><p>The browser creates a non-exportable private ECDSA P-256 key. A record contains the public key and can be checked offline by signature. It is self-signed and does not authenticate an external operator or claim NIST/IEEE compliance. Audit export gives you an external copy of the current chain.</p><h3>Storage and privacy</h3><p>Images, records and the key stay in IndexedDB for this browser and origin. There are no data uploads or analytics. Clearing browser/site data removes this workspace. Imported images are bounded to 128 MiB each and 256 MiB per workspace. Keep exported evidence and original images if you need them.</p></div>`,btn('Back to workspace','close-modal','arrow',true),true);}
async function restoreFixtures(){if(state.busy)return;if(state.images.some(i=>i.source==='fixture'&&i.status==='ready'))return toast('Ready fixtures are already available in Media inventory.');toast('Generating fresh fixtures…');const fixtures=await Promise.all([0,1,2].map(createFixture));if(state.images.reduce((n,i)=>n+i.size,0)+fixtures.reduce((n,i)=>n+i.size,0)>256*1048576)return toast('Workspace limit reached. Remove an image before adding fixtures.');const entry=await auditEntry('fixtures.restored',{message:'Three seeded raw images with known PNG, PDF and filename residues.'});await commit({images:fixtures,values:{audit:[...state.audit,entry]}});state.audit.push(entry);state.images.push(...fixtures);state.selected=fixtures[0].id;render();toast('Three fresh research fixtures are ready.');}
async function importImage(file){
  if(!file||state.busy)return;
  if(file.size===0)return toast('This image is empty. Choose a file with image bytes.');
  if(file.size>MAX_IMAGE_SIZE)return toast('This image exceeds the 128 MiB image limit.');
  if(file.size+state.images.reduce((n,i)=>n+i.size,0)>256*1048576)return toast('This would exceed the 256 MiB workspace limit. Remove an image first.');
  if(!/\.(img|raw|bin|dd)$/i.test(file.name))return toast('Choose a raw .img, .raw, .bin or .dd disk image.');
  try{
    toast('Importing image into local browser storage…');
    const buffer=await file.arrayBuffer();const image={id:crypto.randomUUID(),name:file.name.replace(/\.[^.]+$/,''),filename:file.name,size:buffer.byteLength,source:'import',created:new Date().toISOString(),status:'ready',manifest:[],buffer};
    const entry=await auditEntry('image.imported',{name:image.name,size:image.size});await commit({images:[image],values:{audit:[...state.audit,entry]}});
    state.audit.push(entry);state.images.push(image);state.selected=image.id;nav('media');render();toast('Image imported. Your original file is unchanged.');
  }catch(error){toast('Import failed: '+error.message);}
}
function bindDrop(){const el=document.querySelector('#upload-drop');if(!el)return;el.ondragover=ev=>{ev.preventDefault();el.classList.add('dragover');};el.ondragleave=()=>el.classList.remove('dragover');el.ondrop=ev=>{ev.preventDefault();el.classList.remove('dragover');if(ev.dataTransfer.files.length!==1)return toast('Import one image at a time.');importImage(ev.dataTransfer.files[0]);};el.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();document.querySelector('#image-input').click();}};}
document.addEventListener('click',async ev=>{
  if(ev.target.closest('.skip-link')){ev.preventDefault();document.querySelector('#main')?.focus();return;}
  const target=ev.target.closest('[data-action]');if(target){ev.preventDefault();const action=target.dataset.action;if(target.disabled)return;
    try{
      if(action==='nav')nav(target.dataset.route);
      else if(action==='menu'){state.menu=!state.menu;render();}
      else if(action==='help')help();
      else if(action==='close-modal')closeModal();
      else if(action==='erase')prepareErase();
      else if(action==='confirm-erase'){if(!document.querySelector('#erase-consent')?.checked)return;state.selected=document.querySelector('#erase-image').value;await run('erase');}
      else if(action==='inspect')await inspect(target.dataset.id);
      else if(action==='import'){if(state.busy)return toast('Wait for the operation to finish.');document.querySelector('#image-input').click();}
      else if(action==='fixtures')await restoreFixtures();
      else if(action==='scan')await run('scan');
      else if(action==='verify-image'){closeModal();await run('verify');}
      else if(action==='cancel-job')await cancelJob();
      else if(action==='dismiss-job'){state.lastJob=null;render();}
      else if(action==='download-image'){const image=state.images.find(i=>i.id===target.dataset.id);if(image)download(image.buffer,image.filename,'application/octet-stream');}
      else if(action==='remove-image'){
        if(state.busy)return;const image=state.images.find(i=>i.id===target.dataset.id);if(!image)return;
        modal('Remove this workspace image?',`<p class="prose">Remove <strong>${e(image.name)}</strong> and its recovery scan from this browser. Existing signed records and audit history will be kept. Your original file is unchanged.</p>`,btn('Keep image','close-modal')+btn('Remove workspace image','confirm-remove','trash',false,`data-id="${e(image.id)}"`));
      }else if(action==='confirm-remove'){
        if(state.busy)return;const image=state.images.find(i=>i.id===target.dataset.id);if(!image)return;const scans={...state.scans};delete scans[image.id];const entry=await auditEntry('image.removed',{name:image.name,size:image.size});await commit({remove:[image.id],values:{audit:[...state.audit,entry],scans}});state.audit.push(entry);state.scans=scans;state.images=state.images.filter(i=>i.id!==image.id);state.selected=state.images[0]?.id;closeModal();render();toast('Workspace image removed. Evidence records kept.');
      }else if(action==='download-file'){
        const image=selected(),scan=state.scans[image?.id],f=scan?.files[Number(target.dataset.index)];if(!f)return;
        download(image.buffer.slice(f.offset,f.offset+f.length),`candidate_${String(Number(target.dataset.index)+1).padStart(3,'0')}.${f.type.toLowerCase()}`,'application/octet-stream');
      }else if(action==='file-detail'){
        const f=state.scans[selected()?.id]?.files[Number(target.dataset.index)];if(!f)return;
        modal('Candidate structure',`<dl class="detail-grid"><div><dt>Type</dt><dd>${f.type}</dd></div><div><dt>Confidence</dt><dd>${f.confidence}% structural evidence</dd></div><div><dt>Offset</dt><dd class="mono">0x${f.offset.toString(16).toUpperCase()}</dd></div><div><dt>Length</dt><dd>${f.length.toLocaleString()} bytes</dd></div></dl><ul class="check-list">${f.checks.map(c=>`<li>${icon('info')}${e(c)}</li>`).join('')}</ul><p class="prose" style="margin-top:20px">Original filenames are not recovered by carving. A candidate may be incomplete or invalid. Confidence is a heuristic, not a probability.</p>`,btn('Close','close-modal')+btn('Download candidate','download-file','download',true,`data-index="${e(target.dataset.index)}"`));
      }else if(action==='export-scan'){const image=selected(),scan=state.scans[image?.id];if(scan)download({schema:'eraseproof.carving-manifest.v1',image:{name:image.name,size:image.size},...scan},'eraseproof-carving-manifest.json');}
      else if(action==='certificate')await certificateModal(target.dataset.id);
      else if(action==='export-certificate'){const c=state.certificates.find(c=>c.payload.id===target.dataset.id);if(c)download(c,`${c.payload.id}.json`);}
      else if(action==='export-audit')download({schema:'eraseproof.audit.v1',exportedAt:new Date().toISOString(),head:state.audit.at(-1)?.hash||'0'.repeat(64),events:state.audit},'eraseproof-audit.json');
      else if(action==='check-chain'){state.chainValid=await checkChain();render();toast(state.chainValid?'All audit event hashes and links match.':'Audit integrity failed. Export the log for inspection.');}
      else if(action==='verify-certificate')document.querySelector('#certificate-input').click();
      else if(action==='print')window.print();
    }catch(error){toast(error.message||'The operation could not be completed.');}
    return;
  }
  const row=ev.target.closest('[data-image]');if(row){state.selected=row.dataset.image;render();}
  if(ev.target.classList.contains('modal-backdrop'))closeModal();
});
document.addEventListener('change',ev=>{
  if(ev.target.id==='erase-consent')document.querySelector('[data-action="confirm-erase"]').disabled=!ev.target.checked;
  if(ev.target.id==='recovery-image'){state.selected=ev.target.value;state.lastJob=null;render();}
  if(ev.target.id==='media-filter'){state.filter=ev.target.value;document.querySelector('#media-table').innerHTML=mediaTable(true);}
});
document.addEventListener('input',ev=>{if(ev.target.id==='media-search'){state.search=ev.target.value;document.querySelector('#media-table').innerHTML=mediaTable(true);}});
document.addEventListener('keydown',ev=>{
  const root=document.querySelector('#modal-root');if(!root.firstChild)return;
  if(ev.key==='Escape'){closeModal();return;}
  if(ev.key==='Tab'){const focusable=[...root.querySelectorAll('button:not(:disabled),input,select,a[href],[tabindex="0"]')];const first=focusable[0],last=focusable.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first.focus();}}
});
document.querySelector('#image-input').addEventListener('change',ev=>{const file=ev.target.files[0];ev.target.value='';importImage(file);});
document.querySelector('#certificate-input').addEventListener('change',async ev=>{
  const file=ev.target.files[0];ev.target.value='';if(!file)return;
  try{if(file.size>1024*1024)throw new Error('Record is too large. Choose an EraseProof JSON record under 1 MiB.');const record=JSON.parse(await file.text());const valid=await verifyCertificate(record);modal('Check a signed record',`<div class="verification-result ${valid?'':'invalid'}"><h3>${valid?'Signature and payload match':'Record integrity failed'}</h3><p>${valid?'The supplied public key validates the signature and the payload hash matches.':'The payload hash or signature does not match. Treat this record as changed or invalid.'}</p></div><dl class="detail-grid"><div><dt>Image</dt><dd>${e(record.payload.image?.name)}</dd></div><div><dt>Record ID</dt><dd class="mono">${e(record.payload.id)}</dd></div><div class="full"><dt>Payload hash</dt><dd class="mono">${e(record.payloadSha256)}</dd></div></dl><div class="notice">${icon('info')}<span>Signature integrity does not authenticate the signer or independently prove the image was erased. This record uses its own embedded public key.</span></div>`,btn('Done','close-modal','check',true));}catch(error){toast('Could not verify record: '+error.message);}
});
window.addEventListener('hashchange',()=>{const route=location.hash.slice(1);state.route=viewNames[route]?route:'overview';state.menu=false;state.search='';state.filter='all';render();window.scrollTo({top:0});});
window.addEventListener('beforeunload',ev=>{if(state.busy){ev.preventDefault();ev.returnValue='';}});

async function init(){
  try{
    if(!window.isSecureContext||!crypto.subtle)throw new Error('EraseProof needs HTTPS or localhost for cryptographic verification.');
    const [images,audit,certificates,scans,initialized]=await Promise.all([readAllImages(),readState('audit'),readState('certificates'),readState('scans'),readState('initialized')]);
    state.images=images;state.audit=audit||[];state.certificates=certificates||[];state.scans=scans||{};state.chainValid=await checkChain();
    if(!initialized){
      const fixtures=await Promise.all([0,1,2].map(createFixture));const entry=await auditEntry('workspace.initialized',{message:'Three research fixtures created. No physical drives connected.'});
      await commit({images:fixtures,values:{initialized:true,audit:[entry],certificates:[],scans:{}}});state.images=fixtures;state.audit=[entry];
    }
    let savedSelection;try{savedSelection=localStorage.getItem('eraseproof-selected-image');}catch{}
    state.images.sort((a,b)=>a.created.localeCompare(b.created)||a.filename.localeCompare(b.filename));
    state.selected=state.images.some(i=>i.id===savedSelection)?savedSelection:state.images[0]?.id;state.route=viewNames[location.hash.slice(1)]?location.hash.slice(1):'overview';render();
  }catch(error){app.innerHTML=`<main class="initial-loader"><span class="logo-mark">E</span><h1>Workspace could not open.</h1><p>${e(error.message)}</p><p>Allow browser storage and open this site over HTTPS or localhost, then reload.</p><button class="button" onclick="location.reload()">Try again</button></main>`;}
}
init();
